    "EnableConvey": { id: "ns=5;s=::Program:EnableConvey", type: "Boolean" },
    "SpeedPercent": { id: "ns=5;s=::Program:SpeedPercent", type: "Float" },
    "VitesseMMS": { id: "ns=5;s=::Program:VitesseMMS", type: "Float" },
    "CompteurPieces": { id: "ns=5;s=::Tcpt:CompteurPieces", type: "UInt32" }
};
