flow.set("opc_convoyeur", VARS);
const msgs = Object.values(VARS).map(v => ({ topic: v.id + ";datatype=" + v.type, payload: "" }));
return [msgs];

const VARS = flow.get("opc_convoyeur");
if (!VARS) return null;
// Ordre = ordre des sorties de ce nœud (1 sortie par variable)
const ORDER = ["gMarcheConv", "EnableConvey", "SpeedPercent", "VitesseMMS", "CompteurPieces"];
const LABELS = {"gMarcheConv": "Mise sous tension", "EnableConvey": "Mouvement du tapis", "SpeedPercent": "Vitesse de consigne", "VitesseMMS": "Vitesse du tapis", "CompteurPieces": "Pièces"};
const topic = String(msg.topic).split(";datatype")[0];
const name = Object.keys(VARS).find(k => VARS[k].id === topic);
if (!name) return null;
let v = msg.payload;
if (v && typeof v === "object" && "value" in v) v = v.value;
if (typeof v === "number") v = Math.round(v * 100) / 100;
const out = new Array(ORDER.length).fill(null);
const i = ORDER.indexOf(name);
if (i < 0) return null;
out[i] = { payload: v, topic: LABELS[name] || name };
return out;

